-- =====================================================================
-- Brothers Teknoloji - Ürün kataloğunu Supabase'e taşıma
-- Supabase panel > SQL Editor > New query > bu dosyanın tamamını yapıştırın > RUN
-- Tekrar çalıştırmak güvenlidir (var olan ürünleri günceller, silmez).
-- =====================================================================

create table if not exists public.categories (
  id           text primary key,
  name         text not null,
  slug         text not null,
  parent       text references public.categories(id) on delete set null,
  description  text default '',
  sort_order   int  default 0,
  show_on_home boolean default false,
  image        text,
  active       boolean default true,
  updated_at   timestamptz default now()
);

create table if not exists public.products (
  id           text primary key,
  slug         text,
  name         text not null,
  brand        text default '',
  category     text references public.categories(id) on delete set null,
  price        numeric(12,2) not null,           -- satış fiyatı (KDV dahil, zam uygulanmış)
  old_price    numeric(12,2),                    -- üstü çizili eski fiyat
  rating       numeric(3,1) default 0,
  review_count int default 0,
  in_stock     boolean default true,
  stock        int,
  image        text default '',
  tags         jsonb default '[]'::jsonb,
  description  text default '',
  specs        jsonb default '[]'::jsonb,
  variants     jsonb default '[]'::jsonb,
  featured     boolean default false,            -- "Öne Çıkanlar"
  is_new       boolean default false,            -- "Yeni Gelenler"
  active       boolean default true,             -- false = sitede/uygulamada gizli
  sort_order   int default 0,
  created_at   timestamptz default now(),
  updated_at   timestamptz default now()
);

create index if not exists products_category_idx on public.products(category);
create index if not exists products_active_idx on public.products(active);

-- updated_at otomatik güncellensin
create or replace function public.bt_touch_updated_at() returns trigger language plpgsql as $f$
begin new.updated_at = now(); return new; end $f$;
drop trigger if exists products_touch on public.products;
create trigger products_touch before update on public.products for each row execute function public.bt_touch_updated_at();
drop trigger if exists categories_touch on public.categories;
create trigger categories_touch before update on public.categories for each row execute function public.bt_touch_updated_at();

-- Güvenlik: herkes yalnızca aktif kayıtları OKUYABİLİR. Yazma izni herkese açık DEĞİLDİR
-- (site paneli service role anahtarıyla çalışan bir sunucu fonksiyonu üzerinden yazmalı).
alter table public.products   enable row level security;
alter table public.categories enable row level security;
drop policy if exists "products public read" on public.products;
create policy "products public read" on public.products for select using (active = true);
drop policy if exists "categories public read" on public.categories;
create policy "categories public read" on public.categories for select using (active = true);

-- Canlı senkron (Realtime): eklenen/değişen/silinen ürünler anında uygulamaya gider
alter table public.products   replica identity full;
alter table public.categories replica identity full;
do $r$ begin
  begin alter publication supabase_realtime add table public.products;   exception when duplicate_object then null; end;
  begin alter publication supabase_realtime add table public.categories; exception when duplicate_object then null; end;
end $r$;

