  as x(id text, slug text, name text, brand text, category text, price numeric, old_price numeric, rating numeric,
       review_count int, in_stock boolean, stock int, image text, tags jsonb, description text, specs jsonb,
       variants jsonb, featured boolean, is_new boolean, sort_order int)
on conflict (id) do update set slug = excluded.slug, name = excluded.name, brand = excluded.brand, category = excluded.category,
  price = excluded.price, old_price = excluded.old_price, rating = excluded.rating, review_count = excluded.review_count,
  in_stock = excluded.in_stock, stock = excluded.stock, image = excluded.image, tags = excluded.tags,
  description = excluded.description, specs = excluded.specs, variants = excluded.variants,
  featured = excluded.featured, is_new = excluded.is_new, sort_order = excluded.sort_order;

-- Kontrol: aşağıdaki sorgu ürün ve kategori sayısını göstermeli
select (select count(*) from public.products) as urun_sayisi, (select count(*) from public.categories) as kategori_sayisi;
